class TransportError(Exception):
    """Anything that went wrong talking to the server."""


class Timeout(TransportError):
    pass


class ServerError(TransportError):
    def __init__(self, status):
        super().__init__("server error %d" % status)
        self.status = status


class ClientError(TransportError):
    """The request itself was rejected (a 4xx). Sending it again will not help."""

    def __init__(self, status, message=""):
        super().__init__("client error %d %s" % (status, message))
        self.status = status

