class PaymentService:
    """Charges a card through a client that may retry, so every attempt must carry the same key."""

    def __init__(self, client):
        self.client = client

    def charge(self, amount_cents, idempotency_key):
        request = {"op": "charge", "amount": amount_cents, "key": idempotency_key}
        return self.client.send(request)

